          }
        >
          This container uses a semantically correct h2 in the header.
        </Container>
        <Container
          header={
            <Header
              variant="h2"
              actions={
                <SpaceBetween direction="horizontal" size="xs">
                  <Button>Button</Button>
                  <Button>And Button</Button>
                  <Button>And a third Button with very long text</Button>
